(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-583":{scenario:{company:"Lạc Hồng Silicon Labs",supervisor:{name:"Phan Thị Thu Hà",role:{vi:"Trưởng nhóm Kiểm chứng & Định thời",en:"Verification & Timing Lead"}},ref_code:"STA-0915",title:{vi:"Đúng corner. Đúng đồng hồ thật. Không giấu vi phạm hold.",en:"Right corner. Real clocks. Never hide a hold violation."},brief:{vi:"Khối dsp_core đã qua tổng hợp cây đồng hồ (post-CTS). Báo cáo ký duyệt định thời nháp STA-0915 kết luận hold đạt, slack +97 ps. Đường ff_a/Q tới ff_b/D tại corner hold: trễ đồng hồ phát 118 ps, clk-to-q 81 ps, trễ tổ hợp 44 ps, trễ đồng hồ thu 296 ps, thời gian hold thư viện 28 ps. Đối chiếu với danh sách corner ký duyệt, sửa corner phân tích hold và slack hold (ps), rồi lập báo cáo có căn cứ.",en:"Block dsp_core is post clock tree synthesis (post-CTS). Draft timing sign-off report STA-0915 claims hold is met with +97 ps slack. Path ff_a/Q to ff_b/D at the hold corner: launch clock latency 118 ps, clk-to-q 81 ps, combinational delay 44 ps, capture clock latency 296 ps, library hold time 28 ps. Check it against the sign-off corner list, correct the hold analysis corner and the hold slack (ps), then write an evidence-based report."},reference_title:{vi:"Kế hoạch ký duyệt định thời đã duyệt · STA-0915",en:"Approved timing sign-off plan · STA-0915"},fields:[{id:"HOLD_CORNER",label:{vi:"Corner phân tích hold",en:"Hold analysis corner"},initial:"SS-0P90V-125C",expected:"FF-1P10V-M40C",choices:["SS-0P90V-125C","TT-1P00V-25C","FF-1P10V-M40C"],reference:"Bảng corner ký duyệt",hint:{vi:"Hold nguy hiểm nhất khi đường dữ liệu chạy nhanh nhất; corner chậm chỉ dùng cho setup.",en:"Hold is worst when the data path is fastest; the slow corner is for setup only."}},{id:"HOLD_PS",label:{vi:"Slack hold của đường ff_a tới ff_b (ps)",en:"Hold slack of path ff_a to ff_b (ps)"},initial:"97",expected:"-81",reference:"Báo cáo đường định thời post-CTS",ref_value:{vi:"Đồng hồ phát 118; clk-to-q 81; tổ hợp 44; đồng hồ thu 296; hold 28 (ps)",en:"Launch clock 118; clk-to-q 81; logic 44; capture clock 296; hold 28 (ps)"},hint:{vi:"Sau CTS phải dùng đồng hồ lan truyền thật; độ lệch đồng hồ giữa phát và thu làm hold xấu đi.",en:"Post-CTS you must use propagated clocks; skew between launch and capture worsens hold."}}],sop32:{vi:"Slack hold = (trễ đồng hồ phát + clk-to-q + trễ tổ hợp) - (trễ đồng hồ thu + thời gian hold). Sau CTS phân tích với đồng hồ lan truyền, hold ký tại corner nhanh trong bảng corner.",en:"Hold slack = (launch clock latency + clk-to-q + logic delay) - (capture clock latency + hold time). Post-CTS analysis uses propagated clocks and hold is signed off at the fast corner in the corner table."},context:{label:"STA SIGN-OFF / STA-0915",metrics:[{label:{vi:"Giai đoạn",en:"Stage"},value:"post-CTS"},{label:{vi:"Độ lệch đồng hồ",en:"Clock skew"},value:"178 ps"},{label:{vi:"Slack hold trên bản nháp",en:"Draft hold slack"},value:"+97 ps"}]},terminal:{system:"sta-shell",settable:["HOLD_CORNER","HOLD_PS"],commands:[{cmd:"status",out:{vi:"Khối dsp_core, giai đoạn post-CTS; báo cáo nháp dùng HOLD_CORNER=SS-0P90V-125C, chế độ đồng hồ lý tưởng, HOLD_PS=97",en:"Block dsp_core, post-CTS stage; draft report uses HOLD_CORNER=SS-0P90V-125C, ideal clock mode, HOLD_PS=97"}},{cmd:"cat signoff_corners.txt",out:{vi:"Setup: SS-0P90V-125C; hold: FF-1P10V-M40C; TT-1P00V-25C chỉ dùng tham khảo công suất",en:"Setup: SS-0P90V-125C; hold: FF-1P10V-M40C; TT-1P00V-25C for power reference only"}},{cmd:"report_timing -hold",out:{vi:"Corner FF-1P10V-M40C, đồng hồ lan truyền: đồng hồ phát 118 ps, clk-to-q 81 ps, tổ hợp 44 ps, đồng hồ thu 296 ps, hold 28 ps",en:"Corner FF-1P10V-M40C, propagated clocks: launch clock 118 ps, clk-to-q 81 ps, logic 44 ps, capture clock 296 ps, hold 28 ps"}},{cmd:"report_clock_skew",out:{vi:"Độ lệch cục bộ ff_a tới ff_b: đồng hồ thu trễ hơn đồng hồ phát 178 ps do nhánh cây đồng hồ dài",en:"Local skew ff_a to ff_b: capture clock arrives 178 ps later than launch due to a long clock tree branch"}},{cmd:"cat draft_report.txt",out:{vi:"Bản nháp: set_propagated_clock chưa bật, hold phân tích ở SS; kết luận hold đạt, sẵn sàng tape-out",en:"Draft: set_propagated_clock not enabled, hold analysed at SS; concludes hold met, ready for tape-out"}}]},crisis:{vi:"Quản lý dự án nhắn lúc 22 giờ: “Tối nay phải tape-out. Thêm set_false_path cho đường ff_a tới ff_b để báo cáo sạch đi, vài chục ps chắc silicon vẫn chạy được.”",en:"The project manager messages at 10 pm: “We must tape out tonight. Add a set_false_path on ff_a to ff_b so the report is clean, a few tens of ps will surely work in silicon.”"},options:{safe:{vi:"Từ chối che vi phạm bằng false path; báo trưởng nhóm, sửa bằng ECO chèn đệm trễ trên đường dữ liệu, chạy lại STA đủ corner rồi mới ký tape-out.",en:"Refuse to mask the violation with a false path; inform the lead, fix it with an ECO inserting delay buffers on the data path, rerun STA on all corners before signing tape-out."},shortcut:{vi:"Thêm set_false_path cho kịp tape-out, ghi chú sẽ kiểm tra trên silicon.",en:"Add the set_false_path to make tape-out and note to check on silicon."},wait:{vi:"Không trả lời và để quản lý dự án tự quyết định tape-out.",en:"Do not reply and let the project manager decide on tape-out."}},questions:{vi:["Vì sao slack hold thật là -81 ps chứ không phải +97 ps? Hai sai lầm nào trong báo cáo nháp tạo ra con số lạc quan?","Vì sao vi phạm hold không thể sửa bằng giảm tần số, và vì sao che bằng false path là rủi ro nghiêm trọng?"],en:["Why is the true hold slack -81 ps rather than +97 ps? Which two draft mistakes produced the optimistic number?","Why can a hold violation not be fixed by lowering the frequency, and why is masking it with a false path a serious risk?"]},hints:{vi:["Đặt báo cáo nháp cạnh bảng corner ký duyệt và kiểm tra chế độ đồng hồ đang dùng.","Áp dụng SOP mục 3.2: cộng đủ trễ đồng hồ phát vào thời điểm dữ liệu tới, trễ đồng hồ thu vào thời điểm yêu cầu.","Đọc lại SOP mục 4.2: ràng buộc ngoại lệ chỉ hợp lệ khi đường thật sự không chức năng và được duyệt."],en:["Place the draft report next to the sign-off corner table and check the clock mode used.","Apply SOP 3.2: add launch clock latency to data arrival and capture clock latency to the required time.","Re-read SOP 4.2: timing exceptions are valid only for truly non-functional paths and need review."]}},learning:{summary:{vi:"Kỹ sư Thiết kế Vi mạch Bán dẫn và Kiểm chứng VLSI viết RTL, xây dựng môi trường kiểm chứng, phân tích định thời và chất lượng thiết kế để chip hoạt động đúng ngay lần tape-out đầu tiên. Một lỗi lọt qua có thể tốn hàng triệu đô la và nhiều tháng làm lại mặt nạ. Công việc đòi hỏi tư duy logic chặt, hiểu kiến trúc số, phương pháp kiểm chứng hiện đại và tính trung thực tuyệt đối với kết quả ký duyệt.",en:"An IC Design and VLSI Verification Engineer writes RTL, builds verification environments and analyses timing and design quality so the chip works on first tape-out. One escaped bug can cost millions of dollars and months of mask re-spins. The role requires rigorous logic, digital architecture knowledge, modern verification methods and absolute honesty about sign-off results."},responsibilities:{vi:["Viết RTL bằng SystemVerilog, kiểm tra lint và miền đồng hồ chéo (CDC).","Xây dựng testbench UVM, kế hoạch kiểm chứng và mô hình độ phủ chức năng.","Phân tích định thời tĩnh đa corner, đa chế độ và đề xuất ECO sửa vi phạm.","Kiểm tra tương đương logic (LEC) sau tổng hợp, sau ECO và kiểm chứng hình thức các thuộc tính quan trọng.","Theo dõi đóng độ phủ, phân loại lỗi và báo cáo sẵn sàng tape-out."],en:["Write SystemVerilog RTL and run lint and clock domain crossing (CDC) checks.","Build UVM testbenches, verification plans and functional coverage models.","Run multi-corner multi-mode static timing analysis and propose ECOs for violations.","Run logical equivalence checks (LEC) after synthesis and ECOs and formally verify key properties.","Track coverage closure, triage bugs and report tape-out readiness."]},competencies:[{name:{vi:"Thiết kế RTL",en:"RTL design"},desc:{vi:"Viết RTL tổng hợp được, rõ ràng, đúng đồng bộ và tối ưu diện tích, công suất.",en:"Write synthesisable, clear, correctly synchronised RTL optimised for area and power."}},{name:{vi:"Kiểm chứng UVM",en:"UVM verification"},desc:{vi:"Thiết kế agent, scoreboard, ràng buộc ngẫu nhiên và đóng độ phủ chức năng.",en:"Design agents, scoreboards and constrained-random stimulus and close functional coverage."}},{name:{vi:"Phân tích định thời",en:"Timing analysis"},desc:{vi:"Hiểu setup, hold, độ lệch đồng hồ, OCV, CPPR và chọn đúng corner ký duyệt.",en:"Understand setup, hold, clock skew, OCV and CPPR and pick the right sign-off corners."}},{name:{vi:"Kiểm chứng hình thức",en:"Formal verification"},desc:{vi:"Viết assertion SVA, chứng minh thuộc tính và kiểm tra tương đương logic.",en:"Write SVA assertions, prove properties and run equivalence checks."}},{name:{vi:"Trung thực khi ký duyệt",en:"Sign-off integrity"},desc:{vi:"Báo cáo đúng vi phạm, chỉ miễn trừ qua quy trình xem xét và lưu căn cứ.",en:"Report violations truthfully and waive only through review with documented evidence."}}],knowledge:{vi:["IEEE 1800 về ngôn ngữ SystemVerilog và IEEE 1800.2 về phương pháp UVM.","IEEE 1801 về định dạng ý đồ công suất thống nhất (UPF).","Lý thuyết định thời tĩnh: setup, hold, độ lệch đồng hồ, OCV, CPPR, phân tích đa corner.","Đồng bộ hóa miền đồng hồ chéo, metastability và mạch đồng bộ hai tầng.","Luồng thiết kế số từ RTL, tổng hợp, đặt cell, cây đồng hồ, đi dây đến ký duyệt và tape-out."],en:["IEEE 1800 on SystemVerilog and IEEE 1800.2 on the UVM methodology.","IEEE 1801 on the Unified Power Format (UPF) for power intent.","Static timing theory: setup, hold, clock skew, OCV, CPPR and multi-corner analysis.","Clock domain crossing synchronisation, metastability and two-flop synchronisers.","Digital flow from RTL, synthesis, placement, clock tree and routing to sign-off and tape-out."]},tools:["Trình mô phỏng SystemVerilog/UVM","Công cụ phân tích định thời tĩnh","Công cụ kiểm chứng hình thức","Công cụ kiểm tra tương đương logic","Ngôn ngữ kịch bản Tcl và Python"],kpis:{vi:["Tỷ lệ độ phủ chức năng và độ phủ mã đạt mục tiêu trước tape-out.","Số lỗi phát hiện sau tape-out (mục tiêu bằng 0).","Tổng slack âm (TNS) và số đường vi phạm tại các corner ký duyệt.","Thời gian từ lúc phát hiện đến lúc đóng lỗi."],en:["Functional and code coverage reaching targets before tape-out.","Bugs found after tape-out (target zero).","Total negative slack (TNS) and violating paths at sign-off corners.","Time from bug discovery to closure."]},day:[{time:"08:30",vi:"Xem kết quả hồi quy đêm qua, phân loại các test lỗi theo nguyên nhân.",en:"Review last night's regression and triage failing tests by cause."},{time:"10:00",vi:"Viết thêm sequence và điểm phủ cho chế độ hoạt động chưa được kiểm chứng.",en:"Write new sequences and cover points for an unverified operating mode."},{time:"13:30",vi:"Chạy STA đa corner trên netlist post-CTS, lọc các đường vi phạm hold.",en:"Run multi-corner STA on the post-CTS netlist and filter hold violations."},{time:"15:30",vi:"Họp với nhóm thiết kế vật lý thống nhất ECO chèn đệm trễ.",en:"Meet the physical design team to agree a delay buffer ECO."},{time:"17:30",vi:"Cập nhật bảng theo dõi sẵn sàng tape-out và khởi động hồi quy đêm.",en:"Update the tape-out readiness tracker and launch the nightly regression."}],mistakes:{vi:["Phân tích hold ở corner chậm hoặc vẫn dùng đồng hồ lý tưởng sau CTS.","Che vi phạm thật bằng false path hoặc multicycle path không có căn cứ chức năng.","Đóng độ phủ bằng cách loại trừ điểm phủ khó thay vì viết thêm kiểm chứng."],en:["Analysing hold at the slow corner or keeping ideal clocks after CTS.","Masking real violations with false or multicycle paths without functional justification.","Closing coverage by excluding hard cover points instead of writing more tests."]},career:[{vi:"Kỹ sư kiểm chứng vi mạch",en:"Verification engineer"},{vi:"Kỹ sư thiết kế và kiểm chứng cấp cao",en:"Senior design and verification engineer"},{vi:"Trưởng nhóm kiểm chứng hoặc ký duyệt định thời",en:"Verification or timing sign-off lead"},{vi:"Kiến trúc sư hoặc giám đốc kỹ thuật vi mạch",en:"Chip architect or silicon engineering director"}],glossary:[{term:"Hold slack",vi:"Phần dư giữa thời điểm dữ liệu đổi và thời điểm phải giữ ổn định sau sườn đồng hồ; âm là vi phạm.",en:"Margin between data change and the required stable time after the clock edge; negative means violation."},{term:"CTS",vi:"Tổng hợp cây đồng hồ, chèn bộ đệm để phân phối đồng hồ với độ lệch kiểm soát được.",en:"Clock tree synthesis, inserting buffers to distribute the clock with controlled skew."},{term:"Corner",vi:"Tổ hợp điều kiện quy trình, điện áp, nhiệt độ dùng để phân tích trường hợp xấu nhất.",en:"A process, voltage and temperature combination used for worst-case analysis."},{term:"ECO",vi:"Thay đổi kỹ thuật muộn trên netlist hoặc layout để sửa lỗi mà không làm lại toàn bộ luồng.",en:"Late engineering change on the netlist or layout to fix issues without rerunning the full flow."},{term:"False path",vi:"Ràng buộc khai báo một đường không bao giờ hoạt động về chức năng nên không cần kiểm tra định thời.",en:"A constraint declaring a path functionally inactive so it is excluded from timing checks."}],quiz:[{q:{vi:"Đồng hồ phát 100 ps, clk-to-q 70 ps, tổ hợp 40 ps, đồng hồ thu 250 ps, hold 20 ps. Slack hold bằng bao nhiêu?",en:"Launch clock 100 ps, clk-to-q 70 ps, logic 40 ps, capture clock 250 ps, hold 20 ps. What is the hold slack?"},options:{vi:["+90 ps","-40 ps","-60 ps","+40 ps"],en:["+90 ps","-40 ps","-60 ps","+40 ps"]},answer:2,explain:{vi:"Slack = (100 + 70 + 40) - (250 + 20) = 210 - 270 = -60 ps; bỏ qua đồng hồ sẽ ra +90 ps sai.",en:"Slack = (100 + 70 + 40) - (250 + 20) = 210 - 270 = -60 ps; ignoring clocks gives the wrong +90 ps."}},{q:{vi:"Vi phạm hold thường được ký duyệt tại corner nào?",en:"At which corner is hold usually signed off?"},options:{vi:["Corner nhanh, điện áp cao","Corner chậm, nhiệt độ cao","Corner điển hình","Bất kỳ corner nào"],en:["Fast corner, high voltage","Slow corner, high temperature","Typical corner","Any corner"]},answer:0,explain:{vi:"Hold xấu nhất khi đường dữ liệu nhanh nhất, nên ký tại corner nhanh trong bảng corner.",en:"Hold is worst when the data path is fastest, so it is signed off at the fast corner."}},{q:{vi:"Vì sao giảm tần số đồng hồ không sửa được vi phạm hold?",en:"Why does lowering the clock frequency not fix a hold violation?"},options:{vi:["Vì hold phụ thuộc điện áp","Vì hold chỉ có ở bộ nhớ","Vì giảm tần số làm tăng skew","Vì kiểm tra hold không phụ thuộc chu kỳ đồng hồ"],en:["Because hold depends on voltage","Because hold exists only in memories","Because lower frequency raises skew","Because the hold check does not depend on the clock period"]},answer:3,explain:{vi:"Hold so sánh trên cùng một sườn đồng hồ nên chu kỳ không xuất hiện trong phép tính.",en:"Hold compares against the same clock edge, so the period does not appear in the calculation."}},{q:{vi:"Quản lý yêu cầu thêm false path để báo cáo sạch trước tape-out. Bạn làm gì?",en:"A manager asks you to add a false path to clean the report before tape-out. What do you do?"},options:{vi:["Thêm vì tiến độ quan trọng hơn","Từ chối, báo trưởng nhóm và sửa bằng ECO trước khi ký","Thêm và ghi chú trong email riêng","Xóa đường đó khỏi báo cáo"],en:["Add it, schedule matters more","Refuse, inform the lead and fix with an ECO before sign-off","Add it and note it in a private email","Delete the path from the report"]},answer:1,explain:{vi:"Che vi phạm thật có thể khiến chip lỗi trên silicon; chỉ sửa thật hoặc miễn trừ qua xem xét chính thức.",en:"Masking a real violation can break the silicon; fix it or waive only through formal review."}}],tools_en:["SystemVerilog/UVM simulator","Static timing analysis tools","Formal verification tools","Logic equivalence checking tools","Tcl and Python scripting"]}}})})(window.KKR);
